<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/vendor/autoload.php';
use Services\Inventory\ResolucionArticulos as R;
use Services\Inventory\InventarioError;
$n=0;$a=static function(bool $v,string $m)use(&$n){if(!$v)throw new RuntimeException($m);$n++;};
$no=static function(callable $fn,string $codigo)use($a){try{$fn();$a(false,'Debió rechazar '.$codigo);}catch(InventarioError $e){$a($e->codigo===$codigo,'Código esperado '.$codigo.', recibido '.$e->codigo);}};
$articulos=[1=>['unidad'=>'g','activo'=>1,'costo'=>'0.0100'],2=>['unidad'=>'g','activo'=>1,'costo'=>'0.0200'],3=>['unidad'=>'pza','activo'=>1,'costo'=>null],4=>['unidad'=>'ml','activo'=>1,'costo'=>'0.1000']];
$recetas=[10=>['articulo_id'=>2,'unidad_id'=>2,'publicada'=>1,'rendimiento'=>'100.000','unidad'=>'g','componentes'=>[['articulo_id'=>1,'cantidad'=>'200.000','unidad'=>'g','modalidad'=>'almacenado','version_receta_id'=>null]]],11=>['articulo_id'=>3,'unidad_id'=>2,'publicada'=>1,'rendimiento'=>'12.000','unidad'=>'pza','componentes'=>[['articulo_id'=>2,'cantidad'=>'60.000','unidad'=>'g','modalidad'=>'desglosar','version_receta_id'=>10]]]];
$loadA=static fn($id)=>$articulos[$id]??null;$loadR=static fn($id)=>$recetas[$id]??null;
$root=['articulo_id'=>3,'cantidad'=>'1.000','unidad'=>'pza','modalidad'=>'desglosar','version_receta_id'=>11];
$run=static fn($roots,$aa=null,$rr=null,$orig=[], $exigir=false)=>R::resolver($roots,2,$aa??$loadA,$rr??$loadR,$orig,$exigir);
$p=$run([$root]);$a($p['lineas'][0]['cantidad']==='10.000','Dos niveles y rendimiento 12');$a($p['costo_unitario']==='0.1000','Costo exacto');
$stored=$root;$stored['modalidad']='almacenado';$stored['version_receta_id']=null;$p=$run([$stored]);$a(count($p['lineas'])===1&&$p['lineas'][0]['articulo_id']===3,'Detener en terminado');$a($p['costo_unitario']===null,'Costo desconocido no es cero');
$p=$run([$stored,['articulo_id'=>4,'cantidad'=>'150.000','unidad'=>'ml','modalidad'=>'almacenado','version_receta_id'=>null]]);$a(count($p['lineas'])===2,'Mixto sin doble consumo');
$p=$run([['articulo_id'=>1,'cantidad'=>'1.000','unidad'=>'kg','modalidad'=>'almacenado','version_receta_id'=>null]]);$a($p['lineas'][0]['cantidad']==='1000.000','Conversión kg/g');
$no(fn()=>$run([$root],null,null,[],true),'ALMACEN_ORIGEN_FALTANTE');
$no(fn()=>$run([$root],null,null,[1=>['almacen_id'=>2,'unidad_id'=>3,'activo'=>1]],true),'ALMACEN_ORIGEN_FALTANTE');
$p=$run([$root],null,null,[1=>['almacen_id'=>2,'unidad_id'=>2,'activo'=>1]],true);$a($p['lineas'][0]['almacen_id']===2,'Origen propio explícito');
$bad=$root;$bad['cantidad']='0.000';$no(fn()=>$run([$bad]),'CANTIDAD_INVALIDA');$bad['cantidad']=1.2;$no(fn()=>$run([$bad]),'DECIMAL_INVALIDO');
$bad=$root;$bad['unidad']='g';$no(fn()=>$run([$bad]),'UNIDAD_INCOMPATIBLE');$bad=$root;$bad['version_receta_id']=10;$no(fn()=>$run([$bad]),'VERSION_INVALIDA');
$disabled=$articulos;$disabled[1]['activo']=0;$no(fn()=>$run([$root],static fn($id)=>$disabled[$id]??null),'ARTICULO_INACTIVO');
$private=$recetas;$private[10]['unidad_id']=3;$no(fn()=>$run([$root],null,static fn($id)=>$private[$id]??null),'RECETA_AJENA');$private[10]['global']=1;$a($run([$root],null,static fn($id)=>$private[$id]??null)['lineas'][0]['cantidad']==='10.000','Versión Global no comparte stock');
$cycle=$recetas;$cycle[10]['componentes']=[['articulo_id'=>3,'cantidad'=>'1.000','unidad'=>'pza','modalidad'=>'desglosar','version_receta_id'=>11]];$no(fn()=>$run([$root],null,static fn($id)=>$cycle[$id]??null),'RECETA_CIRCULAR');
$precision=$recetas;$precision[11]['rendimiento']='7.000';$no(fn()=>$run([$root],null,static fn($id)=>$precision[$id]??null),'PRECISION_INCOMPATIBLE');
$merma=$recetas;$merma[10]['componentes'][0]['merma']='20.000';$a($run([$root],null,static fn($id)=>$merma[$id]??null)['lineas'][0]['cantidad']==='12.500','Merma exacta anidada');
$aj=R::ajustar([$stored],[['accion'=>'agregar','articulo_id'=>4,'cantidad'=>'10.000','unidad'=>'ml','modalidad'=>'almacenado','version_receta_id'=>null]]);$a(count($run($aj)['lineas'])===2,'Complemento de servicio');
$no(fn()=>R::ajustar([$stored],[['accion'=>'quitar','articulo_id'=>1,'cantidad'=>'1.000','unidad'=>'g']]),'SUSTITUCION_INVALIDA');
$no(fn()=>R::ajustar([$stored],[['accion'=>'quitar','articulo_id'=>3,'cantidad'=>'2.000','unidad'=>'pza']]),'CANTIDAD_INVALIDA');
$no(fn()=>R::ajustar([$stored],[['accion'=>'agregar','articulo_id'=>4,'cantidad'=>'1.000','unidad'=>'ml','etapa'=>'produccion']]),'VARIANTE_PRODUCCION');
$aj=R::ajustar([$root],[['accion'=>'sustituir','articulo_id'=>3,'cantidad'=>'1.000','unidad'=>'pza','nuevo'=>['articulo_id'=>2,'cantidad'=>'5.000','unidad'=>'g','modalidad'=>'desglosar','version_receta_id'=>10]]]);$a($run($aj)['lineas'][0]['cantidad']==='10.000','Sustituir preparación y respetar su modalidad');
$many=array_fill(0,1001,$root);$no(fn()=>$run($many),'COMPOSICION_INVALIDA');
$deep=$recetas;$deep[11]['componentes'][]=['articulo_id'=>4,'cantidad'=>'120.000','unidad'=>'ml','modalidad'=>'almacenado','version_receta_id'=>null];
$milk=R::aplicarVariantes([$root],[['accion'=>'sustituir','articulo_id'=>4,'cantidad'=>'10.000','unidad'=>'ml','nuevo'=>['articulo_id'=>1,'cantidad'=>'5.000','unidad'=>'g','modalidad'=>'almacenado','version_receta_id'=>null]]],2,$loadA,static fn($id)=>$deep[$id]??null);
$a($run($milk)['lineas'][0]['cantidad']==='15.000','Variante modifica preparación al momento antes de resolver');
$no(fn()=>R::aplicarVariantes([$stored],[['accion'=>'quitar','articulo_id'=>1,'cantidad'=>'1.000','unidad'=>'g']],2,$loadA,$loadR),'SUSTITUCION_INVALIDA');
$grande=R::aplicarVariantes([['articulo_id'=>4,'cantidad'=>'120.000','unidad'=>'ml','modalidad'=>'almacenado','version_receta_id'=>null]],[['accion'=>'sustituir','articulo_id'=>4,'cantidad'=>'120.000','unidad'=>'ml','nuevo'=>['articulo_id'=>1,'cantidad'=>'120.000','unidad'=>'g','modalidad'=>'almacenado','version_receta_id'=>null]],['accion'=>'agregar','articulo_id'=>4,'cantidad'=>'120.000','unidad'=>'ml','modalidad'=>'almacenado','version_receta_id'=>null]],2,$loadA,$loadR);
$a($run($grande)['lineas'][0]['cantidad']==='240.000'&&count($run($grande)['lineas'])===1,'Grande conserva sustitución proporcional de toda la leche, incluso con otro orden de opciones');
$coffee=['articulo_id'=>3,'unidad_id'=>2,'publicada'=>1,'rendimiento'=>'1.000','unidad'=>'pza','componentes'=>[['articulo_id'=>4,'cantidad'=>'120.000','unidad'=>'ml','modalidad'=>'almacenado','version_receta_id'=>null]]];
$nested=R::aplicarVariantes([['articulo_id'=>3,'cantidad'=>'1.000','unidad'=>'pza','modalidad'=>'desglosar','version_receta_id'=>30]],[['accion'=>'agregar','articulo_id'=>4,'cantidad'=>'120.000','unidad'=>'ml','modalidad'=>'almacenado','version_receta_id'=>null],['accion'=>'sustituir','articulo_id'=>4,'cantidad'=>'120.000','unidad'=>'ml','nuevo'=>['articulo_id'=>1,'cantidad'=>'120.000','unidad'=>'g','modalidad'=>'almacenado','version_receta_id'=>null]]],2,$loadA,static fn($id)=>$id===30?$coffee:$loadR($id));
$a($run($nested)['lineas'][0]['cantidad']==='240.000'&&count($run($nested)['lineas'])===1,'Sustitución proporcional incluye leche interna de la elaboración y leche adicional');
echo "Resolución M2: {$n} comprobaciones OK.\n";
